if (res.getStatus() === 200 && res.getBody().success) {
  const rows = res.getBody().data.items;
  const wanted = bru.getEnvVar('variantId');
  const usable = x => Number(x.sellingPrice) > 0 && Number(x.sellingPrice)*2 <= 9999999999999.99;
  const sku = wanted ? rows.find(x => x.variantId === wanted) : rows.find(usable);
  if (!sku || !usable(sku)) throw new Error('Can SKU NORMAL ACTIVE gia duong, tong 2 bo khong vuot DECIMAL(15,2). variantId tuy chon phai nam trong 100 ket qua dau.');
