  const definition = {productCode:code,name:'Bruno combo test',categoryId:bru.getEnvVar('categoryId'),brandId:null,
    description:'Temporary combo created by Bruno smoke flow',items:[{variantId:sku.variantId,quantity:1}],
    packagePrice:Number(sku.sellingPrice),validFrom:new Date(Date.now()-60000).toISOString(),
    validUntil:new Date(Date.now()+86400000).toISOString(),componentGroups:[]};
  bru.setVar('bundleDefinition',JSON.stringify(definition));
  bru.setVar('bundleCode',code);
  bru.setVar('variantId',sku.variantId);
  bru.setVar('packagePrice',Number(sku.sellingPrice));
}

